#!/usr/bin/env sh
set -eu

: "${POSTGRES_USER:?POSTGRES_USER is required}"
: "${POSTGRES_DB:?POSTGRES_DB is required}"

BOOTSTRAP_POSTGRES_HOST="${BOOTSTRAP_POSTGRES_HOST:-}"
BOOTSTRAP_POSTGRES_PORT="${BOOTSTRAP_POSTGRES_PORT:-5432}"
TEST_NETWORK_DB_PATH="${TEST_NETWORK_DB_PATH:-/var/chainDB}"
DEPLOYED_CONTRACTS_PATH="${ADAPTER_BLOCKCHAIN_DEPLOYED_CONTRACTS_PATH:-${TEST_NETWORK_DB_PATH%/}/deployed_contracts.json}"

attempt=0
while [ ! -s "$DEPLOYED_CONTRACTS_PATH" ] && [ "$attempt" -lt 60 ]; do
    attempt=$((attempt + 1))
    sleep 1
done

if [ ! -s "$DEPLOYED_CONTRACTS_PATH" ]; then
    echo "deployed token contract manifest not found: $DEPLOYED_CONTRACTS_PATH" >&2
    exit 1
fi

deployed_token_address() {
    symbol="$1"
    sed -n "/\"$symbol\"[[:space:]]*:/,/}/ s/.*\"address\"[[:space:]]*:[[:space:]]*\"\([^\"]*\)\".*/\1/p" "$DEPLOYED_CONTRACTS_PATH" | head -n 1
}

validate_contract_address() {
    symbol="$1"
    address="$2"
    if ! printf '%s' "$address" | grep -Eq '^0x[0-9a-fA-F]{40}$'; then
        echo "$symbol contract address is missing or invalid in $DEPLOYED_CONTRACTS_PATH" >&2
        exit 1
    fi
}

LOCAL_USDC_CONTRACT_ADDRESS="${LOCAL_USDC_CONTRACT_ADDRESS:-$(deployed_token_address USDC)}"
LOCAL_USDT_CONTRACT_ADDRESS="${LOCAL_USDT_CONTRACT_ADDRESS:-$(deployed_token_address USDT)}"
validate_contract_address "USDC" "$LOCAL_USDC_CONTRACT_ADDRESS"
validate_contract_address "USDT" "$LOCAL_USDT_CONTRACT_ADDRESS"

PSQL_HOST_OPTION=""
PSQL_PORT_OPTION=""
if [ -n "$BOOTSTRAP_POSTGRES_HOST" ]; then
    PSQL_HOST_OPTION="--host=$BOOTSTRAP_POSTGRES_HOST"
    PSQL_PORT_OPTION="--port=$BOOTSTRAP_POSTGRES_PORT"
    if [ -z "${PGPASSWORD:-}" ] && [ -n "${POSTGRES_PASSWORD:-}" ]; then
        export PGPASSWORD="$POSTGRES_PASSWORD"
    fi
fi

psql -v ON_ERROR_STOP=1 \
    -v local_usdc_contract_address="$LOCAL_USDC_CONTRACT_ADDRESS" \
    -v local_usdt_contract_address="$LOCAL_USDT_CONTRACT_ADDRESS" \
    $PSQL_HOST_OPTION \
    $PSQL_PORT_OPTION \
    --username "$POSTGRES_USER" \
    --dbname "$POSTGRES_DB" <<'SQL'
BEGIN;

-- Clean up any existing demo transactions/reservations to keep inventory consistent
DELETE FROM payment_authorizations WHERE payment_id IN (SELECT payment_id FROM payments WHERE order_id IN (SELECT order_id FROM orders WHERE store_id = '44444444-4444-4444-8444-444444444444'));
DELETE FROM payments WHERE order_id IN (SELECT order_id FROM orders WHERE store_id = '44444444-4444-4444-8444-444444444444');
DELETE FROM inventory_reservations WHERE store_id = '44444444-4444-4444-8444-444444444444';
DELETE FROM order_items WHERE order_id IN (SELECT order_id FROM orders WHERE store_id = '44444444-4444-4444-8444-444444444444');
DELETE FROM orders WHERE store_id = '44444444-4444-4444-8444-444444444444';

